package com.bank.learn.service;

import java.util.logging.*;

// Runs the ramp: tiny spike, correctness validation, then wider rollout only if safe.
public class LearningRamp {
    private final Logger log;
    private final MessageBus bus;

    public LearningRamp(Logger log, MessageBus bus) {
        this.log = log;
        this.bus = bus;
    }

    public void run() {
        log.info("STEP 1 FUNDAMENTALS: learn topics, offsets, consumer groups (model first).");

        // STEP 2 — tiny spike: publish ONE event and consume it.
        log.info("STEP 2 SPIKE: publish + consume one settlement event.");
        bus.publish("SETTLE SAV2001->CUR3001 Rs.50000");
        String got = bus.consume();

        // STEP 3 — validate correctness before trusting it with money.
        boolean spikeOk = got != null && bus.getPublished() == bus.getConsumed();
        if (!spikeOk) {
            log.severe("SPIKE FAILED — do NOT scale until correctness is proven.");
            return;
        }
        log.info(() -> "STEP 3 VALIDATE: spike correct (published="
            + bus.getPublished() + " consumed=" + bus.getConsumed() + ").");

        // STEP 4 — scale only after the spike passed.
        log.info("STEP 4 SCALE: now route a batch of real settlement events.");
        for (int i = 1; i <= 100; i++) bus.publish("SETTLE batch #" + i);
        while (!bus.isEmpty()) bus.consume();

        boolean scaleOk = bus.getPublished() == bus.getConsumed();
        log.info(() -> "RESULT: " + (scaleOk ? "all " + bus.getConsumed()
            + " events delivered exactly once — ready for production." : "mismatch!"));
    }
}
